import{_ as r,a0 as a,w as i,s,ao as d,I as e,x as t,a1 as l,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"安卓编年史（19）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（19）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（19）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（19）：Android 4.0 冰淇淋三明治—摩登时代 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/20 - The history of Android","title":"安卓编年史（19）：Android 4.0 冰淇淋三明治—摩登时代","tag":"The history of Android","desc":""},"relativePath":"The history of Android/20 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/20 - The history of Android.md"};function m(g,o,f,y,T,A){const n=a("Link");return i(),s("div",null,[o[25]||(o[25]=d("",34)),e("p",null,[o[1]||(o[1]=t("冰淇淋三明治内置对 ",-1)),l(n,{href:"http://arstechnica.com/gadgets/2011/02/near-field-communications-a-technology-primer/"},{default:p(()=>[...o[0]||(o[0]=[t("NFC",-1)])]),_:1}),o[2]||(o[2]=t(" 的完整支持。尽管之前的设备，比如 Nexus S 也拥有 NFC，得到的支持是有限的并且系统并不能利用芯片做太多事情。4.0 添加了一个“Android Beam”功能，两台拥有 NFC 的安卓 4.0 设备可以借此在设备间来回传输数据。NFC 会传输关于此时屏幕显示的数据，因此在手机显示一个网页的时候使用该功能会将该页面传送给另一部手机。你还可以发送联系人信息、方向导航，以及 Youtube 链接。当两台手机放在一起时，屏幕显示会缩小，点击缩小的界面会发送相关信息。",-1))]),o[26]||(o[26]=e("p",null,"在安卓中，用户不允许删除系统应用，以保证系统完整性。运营商和 OEM 利用该特性并开始将垃圾软件放入系统分区，经常有一些没用的应用存在系统中。安卓 4.0 允许用户禁用任何不能被卸载的应用，意味着该应用还存在于系统中但是不显示在应用抽屉里并且不能运行。如果用户愿意深究设置项，这给了他们一个简单的途径来拿回手机的控制权。",-1)),e("p",null,[o[4]||(o[4]=t("安卓 4.0 可以看做是现代安卓时代的开始。大部分这时发布的谷歌应用只能在安卓 4.0 及以上版本运行。4.0 还有许多谷歌想要好好利用的新 API——至少最初想要——对 4.0 以下的版本的支持就有限了。在冰淇淋三明治和蜂巢之后，谷歌真的开始认真对待软件设计。在 2012 年 1 月，谷歌",-1)),l(n,{href:"http://arstechnica.com/business/2012/01/google-launches-style-guide-for-android-developers/"},{default:p(()=>[...o[3]||(o[3]=[t("最终发布了",-1)])]),_:1}),o[5]||(o[5]=t()),o[6]||(o[6]=e("em",null,"Android Design",-1)),o[7]||(o[7]=t("，一个教安卓开发者如何创建符合安卓外观和感觉的应用的设计指南站点。这是 iOS 在有第三方应用支持开始就在做的事情，苹果还严肃地对待应用的设计，不符合指南的应用都被 App Store 拒之门外。安卓三年以来谷歌没有给出任何公共设计规范文档的事实，足以说明事情有多糟糕。但随着在 Duarte 掌控下的安卓设计革命，谷歌终于发布了基本设计需求。",-1))]),o[27]||(o[27]=e("h3",{id:"google-play-和直接面向消费者出售设备的回归",tabindex:"-1"},[t("Google Play 和直接面向消费者出售设备的回归 "),e("a",{class:"header-anchor",href:"#google-play-和直接面向消费者出售设备的回归","aria-label":"Permalink to “Google Play 和直接面向消费者出售设备的回归”"},"​")],-1)),o[28]||(o[28]=e("p",null,"2012 年 3 月 6 日，谷歌将旗下提供的所有内容统一到 “Google Play”。安卓市场变为了 Google Play 商店，Google Books 变为 Google Play Books，Google Music 变为 Google Play Music，还有 Android Market Movies 变为 Google Play Movies & TV。尽管应用界面的变化不是很大，这四个内容应用都获得了新的名称和图标。在 Play 商店购买的内容会下载到对应的应用中，Play 商店和 Play 内容应用一道给用户提供了易管理的内容体验。",-1)),o[29]||(o[29]=e("p",null,"Google Play 更新是谷歌第一个大的更新周期外更新。四个自带应用都没有通过系统更新获得升级，它们都是直接通过安卓市场/ Play 商店更新的。对单独的应用启用周期外更新是谷歌的重大关注点之一，而能够实现这样的更新，是自姜饼时代开始的工程努力的顶峰。谷歌一直致力于对应用从系统“解耦”，从而让它们能够通过安卓市场/ Play 商店进行分发。",-1)),o[30]||(o[30]=e("p",null,"尽管一两个应用（主要是地图和 Gmail）之前就在安卓市场上，从这里开始你会看到许多更重大的更新，而其和系统发布无关。系统更新需要 OEM 厂商和运营商的合作，所以很难保证推送到每个用户手上。而 Play 商店更新则完全掌握在谷歌手上，给了谷歌一条直接到达用户设备的途径。因为 Google Play 的发布，安卓市场对自身升级到了 Google Play Store，在那之后，图书，音乐以及电影应用都下发了 Google Play 式的更新。",-1)),o[31]||(o[31]=e("p",null,"Google Play 系列应用的设计仍然不尽相同。每个应用的外观和功能各有差异，但暂且来说，一个统一的品牌标识是个好的开始。从品牌标识中去除“安卓”字样是很有必要的，因为很多服务是在浏览器中提供的，不需要安卓设备也能使用。",-1)),e("p",null,[o[9]||(o[9]=t("2012 年 4 月，谷歌",-1)),l(n,{href:"http://arstechnica.com/gadgets/2011/02/near-field-communications-a-technology-primer/"},{default:p(()=>[...o[8]||(o[8]=[t("再次开始通过 Play 商店销售设备",-1)])]),_:1}),o[10]||(o[10]=t("，恢复在 Nexus One 发布时尝试的直接面向消费者销售的方式。尽管距 Nexus One 销售结束仅有两年，但网上购物现在更加寻常，在接触到物品之前就购买它并不像在 2010 年时听起来那么疯狂。",-1))]),o[32]||(o[32]=e("p",null,"谷歌也看到了价格敏感的用户在面对 Nexus One 的 530 美元的价格时的反应。第一部销售的设备是无锁的，GSM 版本的 Galaxy Nexus，价格 399 美元。在那之后，价格变得更低。350 美元成为了最近两台 Nexus 设备的入门价，7 英寸 Nexus 平板的价格更是只有 200 美元到 220 美元。",-1)),o[33]||(o[33]=e("p",null,"今天，Play 商店销售八款不同的安卓设备，四款 Chromebook，一款自动调温器，以及许多配件，设备商店已经是谷歌新产品发布的实际地点了。新产品发布总是如此受欢迎，站点往往无法承载如此大的流量，新 Nexus 手机也在几小时内售空。",-1)),o[34]||(o[34]=e("hr",null,null,-1)),o[35]||(o[35]=e("p",null,[e("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),e("p",null,[l(n,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...o[11]||(o[11]=[t("Ron Amadeo",-1)])]),_:1}),o[13]||(o[13]=t(" / Ron是Ars Technica的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1)),l(n,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...o[12]||(o[12]=[t("@RonAmadeo",-1)])]),_:1})]),o[36]||(o[36]=e("hr",null,null,-1)),e("p",null,[o[15]||(o[15]=t("via: ",-1)),l(n,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/20/"},{default:p(()=>[...o[14]||(o[14]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/20/",-1)])]),_:1})]),e("p",null,[o[18]||(o[18]=t("译者：",-1)),l(n,{href:"https://github.com/alim0x"},{default:p(()=>[...o[16]||(o[16]=[t("alim0x",-1)])]),_:1}),o[19]||(o[19]=t(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:p(()=>[...o[17]||(o[17]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原创翻译，",-1)),l(n,{href:"http://linux.cn/"},{default:p(()=>[...o[21]||(o[21]=[t("Linux中国",-1)])]),_:1}),o[24]||(o[24]=t(" 荣誉推出",-1))])])}const b=r(u,[["render",m]]);export{x as __pageData,b as default};
